function C = bezier3(P, t)
    B = [(1-t).^3;
         3*t.*(1-t).^2;
         3*t.^2.*(1-t);
         t.^3];
    C = P * B;
end

function C = bezier_deg4(Q, t)
    B4 = [(1-t).^4;
          4*t.*(1-t).^3;
          6*t.^2.*(1-t).^2;
          4*t.^3.*(1-t);
          t.^4];
    C = Q * B4;
