  $$
  Q_0=P_0, \quad Q_1=\frac14 P_0+\frac34 P_1, \quad Q_2=\frac12 P_1+\frac12 P_2, \quad Q_3=\frac34 P_2+\frac14 P_3, \quad Q_4=P_3,
